// Every currently-active player (both genders). Filter by gender at the call
// site, the same shape getProRankings uses.
export function getOnTourWeek(gender) {
  return gender ? onTourWeek.filter((r) => r.gender === gender) : onTourWeek;
}

// A single followed player's latest pro match, or null.
export function getLatestPro(playerId) {
  return proLatestByPlayer[playerId] || null;
}


export default onTourWeek;
